long factorial(int n) {
  if (n <= 1) return 1;            /* base case */
  return n * factorial(n - 1);     /* smaller subproblem */
}

long memo[91];                       /* fib(90) fits in a signed 64-bit long */

long fib(int n) {
  if (n < 2) return n;
  if (memo[n]) return memo[n];
  return memo[n] = fib(n - 1) + fib(n - 2);
}

long power(long x, int n) {
  if (n == 0) return 1;
  long half = power(x, n / 2);
  return (n % 2) ? half * half * x : half * half;   /* one recursive call */
}

void subsets(int a[], int n, int i, int chosen[], int k) {
  if (i == n) {                          /* decision made for every element */
    printf("{ ");
    for (int j = 0; j < k; j++) printf("%d ", chosen[j]);
    printf("}\n");
    return;
  }
  subsets(a, n, i + 1, chosen, k);       /* skip a[i] */
  chosen[k] = a[i];                      /* choose a[i] */
  subsets(a, n, i + 1, chosen, k + 1);
  /* nothing to undo: k is passed by value */
}

void permute(int a[], int n, int start) {
  if (start == n) {
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return;
  }
  for (int i = start; i < n; i++) {
    int t = a[start]; a[start] = a[i]; a[i] = t;      /* choose */
    permute(a, n, start + 1);                         /* explore */
    t = a[start]; a[start] = a[i]; a[i] = t;          /* undo */
  }
}

int cols[16];                       /* cols[r] = column of the queen in row r */

int safe(int r, int c) {
  for (int i = 0; i < r; i++)
    if (cols[i] == c || abs(cols[i] - c) == r - i) return 0;   /* column or diagonal */
  return 1;
}

int queens(int n, int r) {           /* number of solutions */
  if (r == n) return 1;
  int count = 0;
  for (int c = 0; c < n; c++) {
    if (!safe(r, c)) continue;         /* prune */
    cols[r] = c;
    count += queens(n, r + 1);
  }
  return count;
}

void hanoi(int n, char from, char to, char via) {
  if (n == 0) return;
  hanoi(n - 1, from, via, to);                     /* move n-1 out of the way */
  printf("disk %d: %c -> %c\n", n, from, to);   /* move the largest */
  hanoi(n - 1, via, to, from);                     /* put n-1 on top of it */
}

/* not tail recursive: multiplication happens after the call returns */
long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }

/* tail recursive: the call is the last action; acc carries the result */
long fact_tail(int n, long acc) { return n <= 1 ? acc : fact_tail(n - 1, acc * n); }

/* the same thing as a loop, which is what an optimizing compiler produces */
long fact_loop(int n) { long acc = 1; while (n > 1) acc *= n--; return acc; }

int sum(int n) {
  if (n == 1) return 1;            /* base case */
  return n + sum(n - 1);           /* recursive case */
}

long fact(int n) {
  if (n == 0) return 1;            /* 0! = 1 */
  return n * fact(n - 1);
}

void printFun(int test) {
  if (test < 1) return;            /* base case */
  printf("%d ", test);             /* before the call: 3 2 1 */
  printFun(test - 1);
  printf("%d ", test);             /* after the call: 1 2 3 */
}

